def P(id,t,age,cat,main,veg,ing,cook,tip,sto=S1):
    steps=['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.',cook,'Blender veya çatalla yaşa uygun kıvamda ezin.','Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.','Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.']
